def book_reservation(user_id: str, origin: str, destination: str, flight_type: str, cabin: str, flights: list, passengers: list, payment_methods: list, total_baggages: int, nonfree_baggages: int, insurance: str):
    """
    Book a reservation.

    Args:
        user_id: The ID of the user to book the reservation such as 'sara_doe_496'`.
        origin: The IATA code for the origin city such as 'SFO'.
        destination: The IATA code for the destination city such as 'JFK'.
        flight_type: The type of flight, EXACTLY one of 'one_way' or 'round_trip'.
        cabin: The cabin class, EXACTLY one of 'basic_economy', 'economy', or 'business'.
        flights: A list of flight segments. Each item MUST be an object with keys 'flight_number' and 'date' (format 'YYYY-MM-DD'), e.g. {"flight_number": "HAT023", "date": "2024-05-26"}. Include EVERY segment.
        passengers: A list of passenger objects. Each MUST use the keys 'first_name', 'last_name', and 'dob' (date of birth, 'YYYY-MM-DD'). Example: {"first_name": "Mia", "last_name": "Li", "dob": "1990-04-05"}. Do NOT use 'date_of_birth'.
        payment_methods: A list of payment objects. Each MUST use the keys 'payment_id' and 'amount' (whole dollars, integer). The 'payment_id' MUST be the EXACT, FULL id copied from the user's profile (e.g. 'credit_card_4959530' — never a shortened or invented id). Example: {"payment_id": "certificate_7504069", "amount": 250}. Do NOT use 'id' or 'type'. The amounts MUST sum to the reservation's total price.
        total_baggages: The total number of baggage items to book the reservation.
        nonfree_baggages: The number of non-free baggage items to book the reservation.
        insurance: Whether the reservation has insurance, EXACTLY 'yes' or 'no'.
    """
    import re

    def _norm_payments(pms):
        # Map common wrong key ('id') to the required 'payment_id', and coerce
        # whole-number float amounts to int. Fires only when 'payment_id' is
        # absent, so a correctly-shaped payment passes through unchanged.
        if not isinstance(pms, list):
            return pms
        out = []
        for pm in pms:
            if isinstance(pm, dict):
                pm = dict(pm)
                if "payment_id" not in pm:
                    for k in ("id", "payment_method_id", "paymentId", "payment_method"):
                        if k in pm:
                            pm["payment_id"] = pm[k]
                            break
                amt = pm.get("amount")
                if isinstance(amt, float) and amt.is_integer():
                    pm["amount"] = int(amt)
            out.append(pm)
        return out

    def _norm_passengers(paxs):
        # Map a wrong date-of-birth key to the required 'dob'. Fires only when
        # 'dob' is absent, so a correctly-shaped passenger is unchanged.
        if not isinstance(paxs, list):
            return paxs
        out = []
        for p in paxs:
            if isinstance(p, dict):
                p = dict(p)
                if "dob" not in p:
                    for k in ("date_of_birth", "dateOfBirth", "birth_date", "birthdate", "dateofbirth", "DOB"):
                        if k in p:
                            p["dob"] = p[k]
                            break
            out.append(p)
        return out

    def _norm_insurance(ins):
        # Coerce anything that is not already 'yes'/'no' into the required enum.
        if ins in ("yes", "no"):
            return ins
        v = str(ins).strip().lower()
        affirm = {"true", "y", "yes", "with insurance", "insurance", "yes please", "add insurance", "1"}
        return "yes" if v in affirm else "no"

    def _user_methods():
        # Return {payment_id: info_dict} from the live user profile, or {} on any
        # failure (primitive returns a plain string on a tool-level error).
        try:
            u = env_get_user_details(user_id=user_id)
        except Exception:
            return {}
        if isinstance(u, dict):
            pm = u.get("payment_methods")
            if isinstance(pm, dict):
                return pm
        return {}

    def _fmt_methods(methods):
        parts = []
        for pid, info in methods.items():
            if isinstance(info, dict):
                src = info.get("source")
                amt = info.get("amount")
                if amt is not None:
                    parts.append(f"{pid} (source={src}, balance={amt})")
                else:
                    parts.append(f"{pid} (source={src})")
            else:
                parts.append(str(pid))
        return parts

    def _fix_payment_ids(pms, valid):
        # If a payment_id is not an exact match but uniquely prefixes exactly one
        # real id (agent truncated it), correct it. Fires only on a non-matching
        # id, so correct ids are untouched.
        if not isinstance(pms, list) or not valid:
            return pms, False
        changed = False
        out = []
        for pm in pms:
            if isinstance(pm, dict) and pm.get("payment_id") not in valid:
                pid = pm.get("payment_id")
                pm = dict(pm)
                if isinstance(pid, str):
                    matches = [v for v in valid if v.startswith(pid) or pid.startswith(v)]
                    if len(matches) == 1:
                        pm["payment_id"] = matches[0]
                        changed = True
            out.append(pm)
        return out, changed

    payment_methods = _norm_payments(payment_methods)
    passengers = _norm_passengers(passengers)
    insurance = _norm_insurance(insurance)

    result = env_book_reservation(user_id=user_id, origin=origin, destination=destination, flight_type=flight_type, cabin=cabin, flights=flights, passengers=passengers, payment_methods=payment_methods, total_baggages=total_baggages, nonfree_baggages=nonfree_baggages, insurance=insurance)

    # ---- Recovery on a FAILED booking only (success returns a reservation dict,
    # not a string). None of these branches can run on a successful call. ----
    if isinstance(result, str) and "does not add up" in result:
        # The primitive states the exact required total. When the reservation is
        # paid with a SINGLE payment method, the correct amount is unambiguous:
        # it MUST equal that total. Correct it and retry once.
        m = re.search(r"total price is (\d+)", result)
        if (m and isinstance(payment_methods, list) and len(payment_methods) == 1
                and isinstance(payment_methods[0], dict)):
            total = int(m.group(1))
            fixed = [dict(payment_methods[0])]
            fixed[0]["amount"] = total
            retry = env_book_reservation(user_id=user_id, origin=origin, destination=destination, flight_type=flight_type, cabin=cabin, flights=flights, passengers=passengers, payment_methods=fixed, total_baggages=total_baggages, nonfree_baggages=nonfree_baggages, insurance=insurance)
            if not isinstance(retry, str):
                return retry
            result = retry
        if isinstance(result, str) and "does not add up" in result:
            paid = sum(pm.get("amount", 0) for pm in payment_methods if isinstance(pm, dict))
            return (result + f". ACTION NEEDED: re-call book_reservation with payment_methods whose "
                    f"'amount' values sum to EXACTLY the total price shown above (you passed {paid}). "
                    f"Adjust the amount on the credit card / gift card / certificate so the sum matches.")

    if isinstance(result, str) and "Payment method" in result and "not found" in result:
        # The agent used a payment_id not on the user's profile. Try to correct a
        # truncated id and retry once; otherwise list the real ids so the agent
        # can pick the right one instead of guessing again.
        valid = _user_methods()
        fixed, changed = _fix_payment_ids(payment_methods, valid)
        if changed:
            retry = env_book_reservation(user_id=user_id, origin=origin, destination=destination, flight_type=flight_type, cabin=cabin, flights=flights, passengers=passengers, payment_methods=fixed, total_baggages=total_baggages, nonfree_baggages=nonfree_baggages, insurance=insurance)
            if not isinstance(retry, str):
                return retry
            result = retry
        if isinstance(result, str) and "not found" in result and valid:
            return (result + ". The user's ACTUAL payment methods on file are: "
                    + "; ".join(_fmt_methods(valid))
                    + ". Re-call book_reservation using one of these EXACT payment_id values.")

    if isinstance(result, str) and ("Not enough seats" in result or "not available" in result or "not found on date" in result):
        return (result + ". Use search_direct_flight / search_onestop_flight to find an "
                "available flight/date/cabin with enough seats before booking again.")

    return result
